<script setup lang="ts">import { onMounted, ref } from 'vue'; import * as echarts from 'echarts'; import { telemetry, stations } from '../mock'; const station=ref('二泵站'); const chart=ref<HTMLElement>(); onMounted(()=>{const c=echarts.init(chart.value!);c.setOption({backgroundColor:'transparent',tooltip:{trigger:'axis'},legend:{textStyle:{color:'#8da5b3'}},xAxis:{type:'category',data:telemetry.map(x=>x.time),axisLabel:{color:'#6f8b9b'}},yAxis:{axisLabel:{color:'#6f8b9b'},splitLine:{lineStyle:{color:'#183444'}}},series:[{name:'流量 m³/h',type:'line',smooth:true,data:telemetry.map(x=>x.flow),lineStyle:{color:'#5be0ca'},areaStyle:{color:'rgba(91,224,202,.12)'}},{name:'压力 MPa',type:'line',smooth:true,data:telemetry.map(x=>x.pressure*1200),lineStyle:{color:'#efb866'}}]})})</script>
<template><div class="page-title"><div><h2>站点趋势</h2><p>查看泵站压力、流量、水位与能耗趋势，缺数区间显式标注</p></div><el-select v-model="station" style="width:150px"><el-option v-for="s in stations" :key="s" :label="s" :value="s"/></el-select></div><div class="grid grid-4"><div class="panel metric"><span class="metric-label">当前流量</span><div class="metric-value">1,086 <small>m³/h</small></div><span class="status-line status-ok"><i/>数据正常 · 10:48</span></div><div class="panel metric"><span class="metric-label">出水压力</span><div class="metric-value">0.74 <small>MPa</small></div><span class="metric-foot">过去 2h +3.1%</span></div><div class="panel metric"><span class="metric-label">水池水位</span><div class="metric-value">3.68 <small>m</small></div><span class="metric-foot">安全区间</span></div><div class="panel metric"><span class="metric-label">运行泵组</span><div class="metric-value">3 / 4 <small>台</small></div><span class="metric-foot">2 号泵待检修</span></div></div><div class="panel" style="margin-top:18px"><div class="panel-head"><h3>24 小时运行趋势</h3><span>流量 / 压力 · Mock 数据</span></div><div ref="chart" class="chart"></div></div></template>
